    function getSocketTypesByName(str2) {
      let result2 = "";
      for (const key in socketTypesByName) {
        const names = socketTypesByName[key].split(" ");
        names.forEach((element) => {
          if (str2.indexOf(element) >= 0) {
            result2 = key;
          }
        });
      }
      return result2;
    }
    function cpuManufacturer(str2) {
      let result2 = str2;
      str2 = str2.toLowerCase();
      if (str2.indexOf("intel") >= 0) {
        result2 = "Intel";
      }
      if (str2.indexOf("amd") >= 0) {
        result2 = "AMD";
      }
      if (str2.indexOf("qemu") >= 0) {
        result2 = "QEMU";
      }
      if (str2.indexOf("hygon") >= 0) {
        result2 = "Hygon";
      }
      if (str2.indexOf("centaur") >= 0) {
        result2 = "WinChip/Via";
      }
      if (str2.indexOf("vmware") >= 0) {
        result2 = "VMware";
      }
      if (str2.indexOf("Xen") >= 0) {
        result2 = "Xen Hypervisor";
      }
      if (str2.indexOf("tcg") >= 0) {
        result2 = "QEMU";
      }
      if (str2.indexOf("apple") >= 0) {
        result2 = "Apple";
      }
      if (str2.indexOf("sifive") >= 0) {
        result2 = "SiFive";
      }
      if (str2.indexOf("thead") >= 0) {
        result2 = "T-Head";
      }
      if (str2.indexOf("andestech") >= 0) {
        result2 = "Andes Technology";
      }
      return result2;
    }
    function cpuBrandManufacturer(res) {
      res.brand = res.brand.replace(/\(R\)+/g, "\xAE").replace(/\s+/g, " ").trim();
      res.brand = res.brand.replace(/\(TM\)+/g, "\u2122").replace(/\s+/g, " ").trim();
      res.brand = res.brand.replace(/\(C\)+/g, "\xA9").replace(/\s+/g, " ").trim();
      res.brand = res.brand.replace(/CPU+/g, "").replace(/\s+/g, " ").trim();
      res.manufacturer = cpuManufacturer(res.brand);
      let parts2 = res.brand.split(" ");
      parts2.shift();
      res.brand = parts2.join(" ");
      return res;
    }
    function getAMDSpeed(brand) {
      let result2 = "0";
      for (let key in AMDBaseFrequencies) {
        if ({}.hasOwnProperty.call(AMDBaseFrequencies, key)) {
          let parts2 = key.split("|");
          let found = 0;
          parts2.forEach((item) => {
            if (brand.indexOf(item) > -1) {
              found++;
            }
          });
          if (found === parts2.length) {
            result2 = AMDBaseFrequencies[key];
          }
        }
      }
      return parseFloat(result2);
    }
